===== drizzle-vs-kysely/spike.mjs
import { PGlite } from '@electric-sql/pglite';
import { PGLiteSocketServer } from '@electric-sql/pglite-socket';
import pg from 'pg';
import { Kysely, PostgresDialect } from 'kysely';
import { drizzle } from 'drizzle-orm/node-postgres';
import { pgTable, integer, text, date, timestamp } from 'drizzle-orm/pg-core';
import { and, eq, isNull, asc, count, sql } from 'drizzle-orm';

const pglite = await PGlite.create();
const server = new PGLiteSocketServer({ db: pglite, port: 0 }); await server.start();
const url = `postgres://postgres:postgres@127.0.0.1:${server.server.address().port}/postgres`;
await pglite.exec(`
  create table task (id int primary key, project_id int not null, status text not null,
                     due_date date, deleted_at timestamptz);
  insert into task select g, 1, (array['todo','doing','done'])[(g % 3) + 1],
                          date '2026-11-01' + (g % 20), null from generate_series(1, 60) g;`);

const cursor = { due: '2026-11-05', id: 10 }, today = '2026-11-10';
const pool = new pg.Pool({ connectionString: url, max: 1 });

// ---------- Kysely ----------
const k = new Kysely({ dialect: new PostgresDialect({ pool }) });
const kPage = k.selectFrom('task').select(['id', 'due_date'])
  .where('project_id', '=', 1).where('deleted_at', 'is', null)
  .where((eb) => eb(eb.refTuple('due_date', 'id'), '>', eb.tuple(cursor.due, cursor.id)))
  .orderBy('due_date').orderBy('id').limit(3);
const kSummary = k.selectFrom('task')
  .where('project_id', '=', 1).where('deleted_at', 'is', null)
  .select((eb) => ['status',
    eb.fn.countAll().as('total'),
    eb.fn.countAll().filterWhere('due_date', '<', today).as('overdue')])
  .groupBy('status').orderBy('status');

// ---------- Drizzle ----------
const task = pgTable('task', {
  id: integer('id').primaryKey(), projectId: integer('project_id').notNull(),
  status: text('status').notNull(), dueDate: date('due_date'), deletedAt: timestamp('deleted_at'),
});
const d = drizzle(pool);
const dPage = d.select({ id: task.id, dueDate: task.dueDate }).from(task)
  .where(and(eq(task.projectId, 1), isNull(task.deletedAt),
             sql`(${task.dueDate}, ${task.id}) > (${cursor.due}, ${cursor.id})`))
  .orderBy(asc(task.dueDate), asc(task.id)).limit(3);
const dSummary = d.select({ status: task.status, total: count(),
    overdue: sql`count(*) filter (where ${task.dueDate} < ${today})`.mapWith(Number) })
  .from(task).where(and(eq(task.projectId, 1), isNull(task.deletedAt)))
  .groupBy(task.status).orderBy(task.status);

const show = (label, q, compiled) => console.log(`\n[${label}]\n  SQL: ${compiled.sql}\n  params: ${JSON.stringify(compiled.params ?? compiled.parameters)}`);
show('kysely keyset', kPage, kPage.compile());           console.log('  rows:', JSON.stringify(await kPage.execute()));
show('drizzle keyset', dPage, dPage.toSQL());            console.log('  rows:', JSON.stringify(await dPage));
show('kysely summary', kSummary, kSummary.compile());    console.log('  rows:', JSON.stringify(await kSummary.execute()));
show('drizzle summary', dSummary, dSummary.toSQL());     console.log('  rows:', JSON.stringify(await dSummary));
await pool.end(); await server.stop(); await pglite.close();
