// Why:   inherits the repo-wide strict baseline; only adds Node runtime types
//        and the folders that belong to this package.
// When:  used by `npm run typecheck -w api`, by ESLint's type-aware rules, and
//        by editors. Runtime execution goes through tsx (no emit needed yet).
{
  "extends": "../tsconfig.base.json",
  "compilerOptions": {
    // TypeScript 6 no longer auto-includes every @types package — list the
    // ambient types we rely on explicitly (Node built-ins: fs, path, http…).
    "types": ["node"],
    // Type-check only. A production build config (emitting to dist/) is added
    // with the GraphQL server in Part 2.
    "noEmit": true
  },
  // Source, tests and the Vitest config are all type-checked and linted.
  "include": ["src", "test", "vitest.config.ts"]
}

/**
 * paths.ts — absolute locations of files the API reads or writes.
 *
 * What: one place that resolves the package root and the well-known paths under it.
 * Why:  npm scripts, tests and editors launch the API from different working
 *       directories (repo root via `-w api`, `api/` itself, Vitest workers). Paths
 *       resolved from `import.meta.dirname` are stable no matter who calls us;
 *       `process.cwd()`-relative paths are not.
 */
import { resolve } from 'node:path';

/** `api/` — this file lives in `api/src/`, so the package root is one level up. */
export const API_ROOT = resolve(import.meta.dirname, '..');

/** Numbered `.sql` migrations — the single source of truth for the database schema. */
export const MIGRATIONS_DIR = resolve(API_ROOT, 'db', 'migrations');

/** Kysely table/column types generated from the migrated schema by `npm run db:codegen`. */
export const GENERATED_DB_TYPES_FILE = resolve(API_ROOT, 'src', 'db', 'types.ts');

/**
 * env.ts — validated runtime configuration for the API.
 *
 * What: reads environment variables (optionally from `api/.env`) and validates
 *       them with zod into a typed, frozen `Env` object.
 * Why:  fail fast. A typo in DATABASE_URL should stop the process at boot with a
 *       readable message, not surface as a connection error mid-request.
 * Who:  called once by each entry point (server, migrate/reset/codegen scripts).
 *       Tests do NOT call it — they pass explicit options so they never depend on
 *       a developer's local .env.
 */
import { existsSync } from 'node:fs';
import { isAbsolute, relative, resolve } from 'node:path';
import { z } from 'zod';
import { API_ROOT } from '../paths.js';

/** Treat `FOO=` (present but empty) the same as "not set" — a common .env pitfall. */
const emptyToUndefined = (value: unknown) => (value === '' ? undefined : value);

const EnvSchema = z.object({
  NODE_ENV: z.enum(['development', 'test', 'production']).default('development'),

  // When set, the API connects to this real Postgres server (Docker, RDS, Neon…).
  // When absent, it boots the embedded PGlite database instead — the zero-setup
  // default for reviewers. Same `pg` driver either way.
  DATABASE_URL: z.preprocess(
    emptyToUndefined,
    z
      .string()
      .regex(/^postgres(ql)?:\/\//, 'must be a postgres:// or postgresql:// connection URL')
      .optional(),
  ),

  // Where embedded PGlite persists its files. Relative paths are anchored at
  // `api/` (not the shell's cwd) so `npm run dev` from any folder hits the same DB.
  PGLITE_DATA_DIR: z
    .string()
    .min(1)
    .default('.pglite')
    .transform((dir) => (isAbsolute(dir) ? dir : resolve(API_ROOT, dir))),

  // Connection-pool size for a real Postgres server. Ignored for PGlite, which is
  // pinned to 1 (see db/database.ts for why).
  DB_POOL_MAX: z.coerce.number().int().min(1).max(100).default(10),
});

export type Env = Readonly<z.infer<typeof EnvSchema>>;

/**
 * Load and validate configuration.
 *
 * How: if `api/.env` exists it is loaded into `process.env` first (Node's built-in
 * loader — variables already set in the real environment win), then the whole
 * environment is validated. Throws with a human-readable list of problems.
 */
export function loadEnv(): Env {
  const envFile = resolve(API_ROOT, '.env');
  if (existsSync(envFile)) process.loadEnvFile(envFile);

  const parsed = EnvSchema.safeParse(process.env);
  if (!parsed.success) {
    throw new Error(`Invalid environment configuration:\n${z.prettifyError(parsed.error)}`);
  }
  return Object.freeze(parsed.data);
}

/** For log lines: show the data dir relative to the package so logs stay short. */
export function describeDataDir(env: Env): string {
  return relative(API_ROOT, env.PGLITE_DATA_DIR) || '.';
}

/**
 * pool.ts — the node-postgres connection pool, with our type-parsing rules.
 *
 * What: creates the `pg.Pool` that Kysely runs every query through, for both the
 *       embedded PGlite server and a real Postgres server.
 * Why:  node-postgres' default parsers have two defaults that silently corrupt data
 *       in this domain, so we override them once, here, for every connection:
 *
 *   1. DATE (`tasks.due_date`) — the default parser builds a JS `Date` at *local*
 *      midnight. On a machine in IST (UTC+5:30), `2026-11-05` became
 *      `2026-11-04T18:30:00Z`: an off-by-one-day bug in due dates, "overdue" logic
 *      and pagination cursors. A calendar date has no time zone, so we keep it as the
 *      exact 'YYYY-MM-DD' string Postgres sent.
 *
 *   2. INT8 / bigint (every `count(*)` result) — the default returns a *string*
 *      ("42"), because int8 can exceed JavaScript's safe-integer range. Counts in this
 *      app never will, so we return a `number` — but we throw instead of silently
 *      rounding if a value ever does exceed 2^53 − 1.
 *
 * Where: per-pool (`types` option), NOT via the global `pg.types.setTypeParser`, so
 *        importing this module never changes the behaviour of other `pg` users.
 */
import pg from 'pg';

/** Postgres type OIDs (from the system catalog `pg_type`) we override. */
const PG_OID = { INT8: 20, DATE: 1082 } as const;

/**
 * Parse an int8 text value into a JS number, refusing to lose precision.
 * Who calls it: node-postgres, for every int8 column in every result row.
 */
export function parseSafeInt8(value: string): number {
  const parsed = Number(value);
  if (!Number.isSafeInteger(parsed)) {
    throw new RangeError(
      `int8 value ${value} exceeds Number.MAX_SAFE_INTEGER; select it ::text instead`,
    );
  }
  return parsed;
}

/**
 * The per-pool parser lookup. node-postgres calls `getTypeParser(oid, format)` for
 * each result column; we answer for our two OIDs and delegate everything else
 * (timestamptz → Date, json → object, …) to the library defaults.
 * Only the default *text* wire format is overridden; binary results are untouched.
 */
const getTypeParser = ((oid: number, format?: 'text' | 'binary') => {
  if (format !== 'binary') {
    if (oid === PG_OID.DATE) return (value: string) => value;
    if (oid === PG_OID.INT8) return parseSafeInt8;
  }
  return pg.types.getTypeParser(oid, format);
}) as typeof pg.types.getTypeParser; // pg's overloaded signature can't be inferred from an arrow fn

export interface PoolOptions {
  /** postgres:// URL — the embedded PGlite socket or a real server. */
  connectionString: string;
  /** Maximum concurrent connections held by this pool. */
  max: number;
}

/**
 * Create the pool. Who: `openDatabase()` (db/database.ts) — the only caller.
 */
export function createPool({ connectionString, max }: PoolOptions): pg.Pool {
  const pool = new pg.Pool({
    connectionString,
    max,
    types: { getTypeParser },
    // Shows up in pg_stat_activity on a real server — tells a DBA which service
    // owns a connection.
    application_name: 'taskboard-api',
  });

  // An idle pooled connection can die (server restart, network blip). Without a
  // listener, node-postgres re-emits that as an *unhandled* 'error' event and the
  // whole process crashes. Log it instead; the pool replaces the client on next use.
  pool.on('error', (error) => {
    console.error('[db] idle connection error (pool will reconnect):', error.message);
  });

  return pool;
}

/**
 * embedded.ts — boots PostgreSQL inside this Node process (PGlite) and exposes it
 * on a local TCP port.
 *
 * What: PGlite is the real Postgres engine compiled to WebAssembly. On its own it
 *       is called through a JS API (`pglite.query()`), which our app does not use.
 *       `PGLiteSocketServer` puts the Postgres *wire protocol* in front of it, so
 *       the standard `pg` driver — and therefore Kysely, kysely-codegen and any
 *       Postgres client — connects to it exactly like a normal server.
 * Why:  the application code path is identical for embedded and real Postgres.
 *       Switching to a real server is a DATABASE_URL change, not a code change.
 * When: on API/script start-up when DATABASE_URL is unset, and once per test file.
 */
import { PGlite } from '@electric-sql/pglite';
import { PGLiteSocketServer } from '@electric-sql/pglite-socket';

export interface EmbeddedPostgres {
  /** Connection URL for the `pg` driver, e.g. postgres://postgres:postgres@127.0.0.1:51234/postgres */
  readonly url: string;
  /** Stop accepting connections, then flush and close the database. */
  stop(): Promise<void>;
}

export interface EmbeddedPostgresOptions {
  /**
   * Directory where PGlite persists its data files. Omit for a throw-away in-memory
   * database (what tests and type generation use: fresh, isolated, fast).
   */
  dataDir?: string | undefined;
}

export async function startEmbeddedPostgres(
  options: EmbeddedPostgresOptions = {},
): Promise<EmbeddedPostgres> {
  // In-memory when no directory is given; otherwise the files survive restarts.
  const pglite = options.dataDir ? await PGlite.create(options.dataDir) : await PGlite.create();

  const server = new PGLiteSocketServer({
    db: pglite,
    // Loopback only: the embedded database must never be reachable from the network.
    host: '127.0.0.1',
    // 0 = let the OS pick a free port, so parallel test files never collide.
    // After start(), getServerConn() reports the real port.
    port: 0,
    // PGlite is ONE Postgres session. The socket server would let several clients
    // share that session, interleaving their statements — one request's open
    // transaction or `SET LOCAL ROLE` would then leak into another request's
    // queries. One connection at a time keeps transactions isolated.
    maxConnections: 1,
  });
  await server.start();

  // The username/password are placeholders: the socket server does not
  // authenticate, and it only listens on loopback (above).
  const url = `postgres://postgres:postgres@${server.getServerConn()}/postgres`;

  return {
    url,
    async stop() {
      // Order matters: stop the socket first so no query arrives mid-close.
      await server.stop();
      await pglite.close();
    },
  };
}

/**
 * database.ts — the one function every entry point uses to get a database handle.
 *
 * What: decides embedded PGlite vs. real Postgres, creates the pool, and wraps it
 *       in a typed Kysely instance.
 * Who:  the GraphQL server (Part 2), the migrate/reset/codegen scripts, and tests.
 * How:  `databaseUrl` set → real server with a normal pool.
 *       `databaseUrl` unset → start embedded PGlite and pin the pool to ONE
 *       connection (PGlite is a single Postgres session — see embedded.ts).
 */
import { CamelCasePlugin, Kysely, PostgresDialect } from 'kysely';
import { startEmbeddedPostgres, type EmbeddedPostgres } from './embedded.js';
import { createPool } from './pool.js';
import type { DB } from './types.js';

export interface OpenDatabaseOptions {
  /** Real Postgres URL. Omit to use embedded PGlite. */
  databaseUrl?: string | undefined;
  /** PGlite persistence directory. Omit for an in-memory database. Ignored with databaseUrl. */
  pgliteDataDir?: string | undefined;
  /** Pool size for a real server. Ignored for PGlite (always 1). */
  poolMax?: number | undefined;
}

export interface Database {
  /** Typed query builder. Table/column types come from the generated `DB` interface. */
  readonly db: Kysely<DB>;
  /** True when running on embedded PGlite (timings are NOT production numbers). */
  readonly embedded: boolean;
  /** Close the pool, then the embedded server if we started one. */
  close(): Promise<void>;
}

export async function openDatabase(options: OpenDatabaseOptions = {}): Promise<Database> {
  let embedded: EmbeddedPostgres | undefined;
  let connectionString = options.databaseUrl;

  if (!connectionString) {
    embedded = await startEmbeddedPostgres({ dataDir: options.pgliteDataDir });
    connectionString = embedded.url;
  }

  const pool = createPool({
    connectionString,
    max: embedded ? 1 : (options.poolMax ?? 10),
  });

  const db = new Kysely<DB>({
    dialect: new PostgresDialect({ pool }),
    // SQL stays snake_case (due_date); TypeScript sees camelCase (dueDate), so rows
    // map straight onto GraphQL fields without per-field resolvers.
    // Caveat: identifiers inside raw sql`` template text are NOT converted —
    // write them in snake_case there.
    plugins: [new CamelCasePlugin()],
  });

  return {
    db,
    embedded: embedded !== undefined,
    async close() {
      await db.destroy(); // ends the pool
      await embedded?.stop();
    },
  };
}

/**
 * migrator.ts — applies the hand-written `.sql` migrations with Kysely's Migrator.
 *
 * What: a tiny MigrationProvider that turns each `NNNN_description.sql` file into a
 *       Kysely migration whose `up` executes the file's SQL verbatim.
 * Why:  the SQL files are the reviewed, commented source of truth for the schema
 *       (Task 1.1 deliverable). Kysely's Migrator contributes the hard parts we
 *       don't want to hand-roll: a `kysely_migration` tracking table, an advisory
 *       lock so two deploys can't migrate concurrently, ordering checks, and — on
 *       Postgres — running the pending batch inside a transaction (all-or-nothing).
 * Policy: forward-only. There are no `down` migrations; a mistake is fixed by a
 *       new migration. Rationale and production rules are in the technical docs.
 */
import { readdir, readFile } from 'node:fs/promises';
import { join } from 'node:path';
import {
  Migrator,
  sql,
  type Kysely,
  type Migration,
  type MigrationProvider,
  type MigrationResult,
} from 'kysely';
import { MIGRATIONS_DIR } from '../paths.js';

/**
 * Accepted file names: 4-digit sequence + snake_case description, e.g.
 * `0001_initial_schema.sql`. Kysely orders migrations by name, so the fixed-width
 * prefix guarantees 0010 runs after 0009 (plain "10_" would sort before "9_").
 */
const MIGRATION_FILE_PATTERN = /^\d{4}_[a-z0-9_]+\.sql$/;

export class SqlFileMigrationProvider implements MigrationProvider {
  constructor(private readonly directory: string) {}

  async getMigrations(): Promise<Record<string, Migration>> {
    const entries = await readdir(this.directory);

    // Only .sql files are migrations; README.md etc. in the folder are ignored.
    const sqlFiles = entries.filter((name) => name.endsWith('.sql')).sort();

    // A misnamed file would silently run in the wrong order — refuse instead.
    const invalid = sqlFiles.filter((name) => !MIGRATION_FILE_PATTERN.test(name));
    if (invalid.length > 0) {
      throw new Error(
        `Invalid migration file name(s): ${invalid.join(', ')} — expected NNNN_snake_case.sql`,
      );
    }

    const migrations: Record<string, Migration> = {};
    for (const fileName of sqlFiles) {
      const statements = await readFile(join(this.directory, fileName), 'utf8');
      migrations[fileName.replace(/\.sql$/, '')] = {
        // sql.raw sends the file as ONE parameter-less query. node-postgres uses the
        // "simple query" protocol for parameter-less queries, which accepts many
        // `;`-separated statements — so a migration file can hold a whole schema.
        up: async (db) => {
          await sql.raw(statements).execute(db);
        },
      };
    }
    return migrations;
  }
}

/**
 * Apply every pending migration. Returns per-migration results for logging;
 * throws (after Kysely has rolled the batch back) if any migration fails.
 * Who: `npm run db:migrate`, `db:reset`, `db:codegen`, and test setup.
 */
export async function migrateToLatest<T>(
  db: Kysely<T>,
  directory: string = MIGRATIONS_DIR,
): Promise<MigrationResult[]> {
  const migrator = new Migrator({ db, provider: new SqlFileMigrationProvider(directory) });
  const { error, results = [] } = await migrator.migrateToLatest();
  if (error) {
    const failed = results.find((result) => result.status === 'Error')?.migrationName;
    throw new Error(`Migration failed${failed ? ` in ${failed}` : ''}: ${String(error)}`, {
      cause: error,
    });
  }
  return results;
}

