    if (oid === PG_OID.DATE) return (value: string) => value;
    if (oid === PG_OID.INT8) return parseSafeInt8;
  }
  return pg.types.getTypeParser(oid, format);
}) as typeof pg.types.getTypeParser; // pg's overloaded signature can't be inferred from an arrow fn

