/**
 * run-script.ts — the shared harness for every `npm run db:*` CLI script.
 *
 * What: runs a script's main function and turns ANY failure — bad env config,
 *       a refused safety check, a broken migration — into one clean log line and
 *       exit code 1.
 * Why:  without it, an error thrown at the top level of an ES module prints a raw
 *       Node stack trace that buries the actual message (e.g. "DATABASE_URL must be
 *       a postgres:// URL"). CI and humans both just need the message + exit code.
 * Note: sets `process.exitCode` instead of calling `process.exit()`, so `finally`
 *       blocks still run and the database is always closed cleanly.
 */
import { errorMessage } from '../lib/errors.js';

export async function runScript(logPrefix: string, main: () => Promise<void>): Promise<void> {
  try {
    await main();
  } catch (error) {
    console.error(`${logPrefix} ${errorMessage(error)}`);
    process.exitCode = 1;
  }
}

/**
 * migrate.ts — `npm run db:migrate` (also the first step of `npm run setup`).
 *
 * What: applies all pending SQL migrations to the configured database.
 * When: after pulling new migrations, or on first setup. Safe to re-run — already
 *       applied migrations are skipped (tracked in the `kysely_migration` table).
 * Exit code: 0 on success, 1 on any failure (CI-friendly, via runScript).
 */
import { loadEnv } from '../config/env.js';
import { openDatabaseFromEnv } from '../db/database.js';
import { logMigrationResults, migrateToLatest } from '../db/migrator.js';
import { runScript } from './run-script.js';

const LOG = '[db:migrate]';

await runScript(LOG, async () => {
  const database = await openDatabaseFromEnv(loadEnv(), LOG);
  try {
    logMigrationResults(await migrateToLatest(database.db), LOG);
  } finally {
    // Always release the pool + embedded server, or the process would hang open.
    await database.close();
  }
});

