// WHAT: boots an embedded Postgres and exposes it on a local TCP port, so the rest of
// the app talks to it exactly like a real Postgres server (via the standard `pg` driver).
import { PGlite } from '@electric-sql/pglite';
import { PGLiteSocketServer } from '@electric-sql/pglite-socket';
import pg from 'pg';

const pglite = await PGlite.create('./.pglite'); // data persisted in ./.pglite (git-ignored)
const server = new PGLiteSocketServer({ db: pglite, port: 0 }); // port 0 = pick any free port
await server.start();
const port = (server.server.address() as { port: number }).port;

// max: 1 — PGlite serves one connection at a time; a bigger pool would just queue.
export const pool = new pg.Pool({
  connectionString: `postgres://postgres:postgres@127.0.0.1:${port}/postgres`,
  max: 1,
});
```

