// Throw-away probe (deleted after running): seed a realistic dataset into schema v1 and
// EXPLAIN every query pattern the Task 1.2 doc will show, as app_user (RLS on).
import { sql } from 'kysely';
import { openDatabase } from './src/db/database.js';
import { migrateToLatest } from './src/db/migrator.js';

const { db: typed, close } = await openDatabase();
await migrateToLatest(typed);
const db = typed.withoutPlugins();
const t0 = Date.now();

// --- seed (as owner): 10 users, 2 orgs (user 8 in both), 3 projects, 24k tasks ---
await sql.raw(`
  INSERT INTO users (email, display_name)
    SELECT 'u' || g || '@example.test', 'User ' || g FROM generate_series(1, 10) g;
  INSERT INTO organizations (name, slug) VALUES ('Acme', 'acme'), ('Globex', 'globex');
  UPDATE organization_settings s SET timezone = CASE o.slug WHEN 'acme' THEN 'Asia/Kolkata' ELSE 'America/New_York' END
    FROM organizations o WHERE o.id = s.organization_id;
  INSERT INTO organization_members (organization_id, user_id, role)
    SELECT o.id, u.id, CASE WHEN u.email IN ('u1@example.test', 'u9@example.test') THEN 'owner' ELSE 'member' END::organization_role
      FROM organizations o JOIN users u ON
        (o.slug = 'acme'   AND u.email IN ('u1@example.test','u2@example.test','u3@example.test','u4@example.test','u5@example.test','u6@example.test','u7@example.test','u8@example.test'))
     OR (o.slug = 'globex' AND u.email IN ('u8@example.test','u9@example.test','u10@example.test'));
  INSERT INTO projects (organization_id, key, name)
    SELECT o.id, k.key, k.key FROM organizations o
      JOIN (VALUES ('acme','WEB'), ('acme','API'), ('globex','OPS')) k(slug, key) ON k.slug = o.slug;
  INSERT INTO tasks (organization_id, project_id, title, status_id, priority, assignee_id, due_date, rank)
