     ORDER BY t.rank, t.id LIMIT 51`,
  IN: sql`SELECT t.id FROM tasks t
     WHERE t.project_id = ${todo.project_id} AND t.status_id = ${todo.id} AND t.deleted_at IS NULL
       AND t.id IN (SELECT tl.task_id FROM task_labels tl WHERE tl.label_id = ANY (${[label]}::uuid[]))
     ORDER BY t.rank, t.id LIMIT 51`,
});
