  await sql`set local role app_user`.execute(trx);
  await sql`select set_config('app.user_id', ${me}, true)`.execute(trx);
  for (const label of ['common', 'rare']) {
    for (const [form, q] of Object.entries(variants(ids[label]!))) {
      const rows = (await q.execute(trx.withoutPlugins())).rows.length;
      const plan = (await sql<Record<string, string>>`EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF) ${q}`.execute(trx.withoutPlugins())).rows.map((r) => Object.values(r)[0]!);
      const buffers = plan.find((l) => l.includes('Buffers'))?.trim();
      const shape = plan.filter((l) => /Scan|Join|Sort|Hash/.test(l) && !l.includes('Buffers')).map((l) => l.trim().replace(/\(actual.*\)/, '').replace(/^->\s*/, '')).slice(0, 4).join(' | ');
      console.log(`${label.padEnd(6)} ${form.padEnd(6)} rows=${String(rows).padEnd(3)} ${buffers?.padEnd(24)} ${shape}`);
    }
  }
});
await close();
