// Throw-away probe (deleted after running): empirically check the Task 1.3 critique's claims.
import { sql, type Kysely } from 'kysely';
import { openDatabase } from './src/db/database.js';
import { migrateToLatest } from './src/db/migrator.js';

const { db: typed, close } = await openDatabase();
await migrateToLatest(typed);
const db = typed.withoutPlugins() as unknown as Kysely<any>;
const run = (q: string) => sql.raw(q).execute(db);
const val = async <T = any>(q: ReturnType<typeof sql>) => ((await q.execute(db)).rows[0] ?? {}) as T;
const as = <T,>(userId: string, fn: (trx: Kysely<any>) => Promise<T>) =>
  db.transaction().execute(async (trx) => {
    await sql`SET LOCAL ROLE app_user`.execute(trx);
    await sql`SELECT set_config('app.user_id', ${userId}, true)`.execute(trx);
    return fn(trx);
  });
const outcome = async (p: Promise<unknown>) => {
  try { const r: any = await p; return `OK ${r?.numAffectedRows !== undefined ? `(${r.numAffectedRows} rows)` : JSON.stringify(r?.rows?.[0] ?? '')}`; }
  catch (e: any) { return `ERROR ${e.code}: ${e.message}`; }
};
const plan = async (trx: Kysely<any>, q: string) =>
  (await sql.raw(`EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS) ${q}`).execute(trx)).rows
    .map((r: any) => Object.values(r)[0] as string).filter((l) => !/^\s*(Planning|Buffers: shared hit=\d+$)/.test(l) || /Buffers/.test(l)).join('\n');
const say = (id: string, ...lines: string[]) => console.log(`\n### ${id}\n${lines.join('\n')}`);

// ---------- seed (owner, bypasses RLS) ----------
await run(`
  INSERT INTO users (email, display_name) SELECT 'u' || g || '@x.test', 'User ' || g FROM generate_series(1, 9) g;
  INSERT INTO organizations (name, slug) VALUES ('Acme', 'acme'), ('Globex', 'globex');
  INSERT INTO organization_members (organization_id, user_id, role)
    SELECT o.id, u.id, r.role::organization_role FROM organizations o
      JOIN (VALUES ('acme','u1','owner'), ('acme','u2','admin'), ('acme','u3','member'), ('acme','u4','member'),
                   ('globex','u9','owner')) r(slug, handle, role) ON r.slug = o.slug
      JOIN users u ON u.email = r.handle || '@x.test';
  INSERT INTO projects (organization_id, key, name) SELECT o.id, k.key, k.key FROM organizations o
    JOIN (VALUES ('acme','WEB'), ('acme','ARC'), ('globex','OPS')) k(slug, key) ON k.slug = o.slug;
  INSERT INTO tasks (organization_id, project_id, title, status_id, assignee_id, rank)
    SELECT p.organization_id, p.id, 'Task ' || g, st.ids[1 + (g % 5)], NULL, 'a' || to_char(g, 'FM0000000')
      FROM projects p
      CROSS JOIN LATERAL (SELECT array_agg(id ORDER BY position) ids FROM task_statuses WHERE project_id = p.id) st
      CROSS JOIN generate_series(1, CASE p.key WHEN 'WEB' THEN 20000 ELSE 20 END) g;
  VACUUM ANALYZE;`);
const id = async (q: string) => (await val<{ id: string }>(sql.raw(q))).id;
const u = Object.fromEntries(await Promise.all(['u1','u2','u3','u4','u9'].map(async (h) => [h, await id(`select id from users where email='${h}@x.test'`)])));
const web = await id(`select id from projects where key='WEB'`);
const ops = await id(`select id from projects where key='OPS'`);
const arc = await id(`select id from projects where key='ARC'`);
const acme = await id(`select id from organizations where slug='acme'`);
const globex = await id(`select id from organizations where slug='globex'`);
const st = async (p: string, name: string) => id(`select id from task_statuses where project_id='${p}' and name='${name}'`);
const todo = await st(web, 'Todo'), done = await st(web, 'Done');
console.log('seeded: 20,000 tasks in WEB (4,000 per status), 20 in ARC, 20 in OPS');

// ---------- S1: default Project.tasks order (CREATED_AT DESC) ----------
await as(u.u3, async (trx) => say('S1 default list ORDER BY created_at DESC LIMIT 50 (as member)',
  await plan(trx, `SELECT id FROM tasks WHERE project_id='${web}' AND deleted_at IS NULL ORDER BY created_at DESC, id DESC LIMIT 50`)));

