   where c.contype = 'f' and c.confrelid = 'users'::regclass order by 1`).execute(db);
say('I1 FK columns referencing users — any index leading with the column?', ...fk.rows.map((r: any) => `${r.col}: ${r.indexed}`));

// C1 -------------------------------------------------------------------------
const t1 = await idOf(`select id from tasks where project_id='${web}' and status_id='${todo}' limit 1`);
await as(u.u3!, (trx) => sql`update tasks set status_id = ${done} where id = ${t1}`.execute(trx));
const c1a = await one(`select completed_at, (select count(*)::int from task_activities where task_id='${t1}') n from tasks where id='${t1}'`);
await run(`select pg_sleep(1.1)`);
await as(u.u2!, (trx) => sql`update task_statuses set category='started' where id=${done}`.execute(trx));
await as(u.u2!, (trx) => sql`update task_statuses set category='completed' where id=${done}`.execute(trx));
const c1b = await one(`select completed_at, (select count(*)::int from task_activities where task_id='${t1}') n from tasks where id='${t1}'`);
say('C1 admin flips Done → started → completed',
  `completed_at: ${new Date(c1a.completed_at).toISOString()} → ${new Date(c1b.completed_at).toISOString()}`,
  `history rows for that task: ${c1a.n} → ${c1b.n}`);

// C6 -------------------------------------------------------------------------
const leaver = await idOf(`insert into users (email, display_name) values ('leaver@x.test','Carol Leaver') returning id`);
await run(`insert into organization_members values ('${acme}', '${leaver}', 'member')`);
const t2 = await idOf(`select id from tasks where project_id='${web}' and status_id='${todo}' offset 1 limit 1`);
await as(leaver, (trx) => sql`insert into task_comments (organization_id, task_id, body) values (${acme}, ${t2}, 'hello')`.execute(trx));
await as(u.u3!, (trx) => sql`update tasks set assignee_id = ${leaver} where id = ${t2}`.execute(trx));
await as(u.u3!, (trx) => sql`update tasks set assignee_id = ${u.u2} where id = ${t2}`.execute(trx));
await run(`delete from organization_members where user_id = '${leaver}'`);
await as(u.u3!, async (trx) => {
  const c = await oneIn(trx, `select c.author_id, u.display_name from task_comments c left join users u on u.id = c.author_id where c.task_id = '${t2}'`);
  const h = (await sql.raw(`select a.old_value, uo.display_name old_name from task_activities a left join users uo on uo.id = (a.old_value #>> '{}')::uuid where a.task_id = '${t2}' and a.field = 'assignee' order by a.created_at, a.id`).execute(trx)).rows as any[];
  say('C6 after Carol left (seen by a remaining member)',
    `comment: author_id stored = ${c.author_id ? 'yes' : 'no'}; author visible = ${c.display_name ?? 'NULL'}`,
    ...h.map((r) => `assignee change old_value=${r.old_value ?? 'null'} → resolves to ${r.old_name ?? 'NULL'}`));
});

// SEC1 -----------------------------------------------------------------------
const sec1 = await outcome(as(u.u2!, (trx) => sql`insert into organization_members (organization_id, user_id, role) values (${acme}, ${u.u9}, 'viewer')`.execute(trx)));
const sec1b = await as(u.u3!, (trx) => oneIn(trx, `select email from users where id = '${u.u9}'`));
say('SEC1 Acme admin adds Globex owner u9 — no invitation or consent', `insert: ${sec1}`, `Acme member can now read u9's email: ${sec1b.email ?? 'no'}`);
await run(`delete from organization_members where organization_id='${acme}' and user_id='${u.u9}'`);

// SEC2 -----------------------------------------------------------------------
const cmt = await as(u.u3!, async (trx) => (await oneIn(trx, `insert into task_comments (organization_id, task_id, body) values ('${acme}', '${t1}', 'original') returning id`)).id as string);
say('SEC2 comment rules',
  `admin rewrites a member's body:        ${await outcome(as(u.u2!, (trx) => trx.updateTable('task_comments').set({ body: 'rewritten by admin' }).where('id', '=', cmt).executeTakeFirst()))}`,
  `admin soft-deletes (moderation):       ${await outcome(as(u.u2!, (trx) => trx.updateTable('task_comments').set({ deleted_at: new Date() }).where('id', '=', cmt).executeTakeFirst()))}`,
  `author un-deletes the moderated one:   ${await outcome(as(u.u3!, (trx) => trx.updateTable('task_comments').set({ deleted_at: null }).where('id', '=', cmt).executeTakeFirst()))}`,
  `body still stored after soft delete:   ${(await one(`select body from task_comments where id='${cmt}'`)).body}`);

// SEC3 -----------------------------------------------------------------------
const intoGlobex = (projectId: string) => outcome(as(u.u3!, (trx) => sql`insert into tasks (organization_id, project_id, title, rank) values (${globex}, ${projectId}, 'x', 'a0')`.execute(trx)));
const s3live = await intoGlobex(ops);
await run(`update projects set archived_at = now() where id = '${ops}'`);
const s3arch = await intoGlobex(ops);
await run(`update projects set archived_at = null where id = '${ops}'`);
const s3none = await intoGlobex('01a1ea70-0000-7000-8000-000000000000');
say('SEC3 Acme member inserts into a Globex project (status omitted)',
  `live project:     ${s3live}`, `archived project: ${s3arch}`, `random id:        ${s3none}`,
  `(Globex OPS Todo status id = ${await statusOf(ops, 'Todo')})`);

// SEC4a ----------------------------------------------------------------------
const arcTask = await idOf(`select id from tasks where project_id='${arc}' limit 1`);
await run(`update projects set archived_at = now() where id = '${arc}'`);
say('SEC4a member edits a task in an ARCHIVED project',
  await outcome(as(u.u3!, (trx) => trx.updateTable('tasks').set({ title: 'still writable' }).where('id', '=', arcTask).executeTakeFirst())));

// SEC4b ----------------------------------------------------------------------
await run(`create function app.probe_a() returns int language sql as 'select 1'`);
await run(`alter default privileges in schema app revoke execute on functions from public`);
await run(`create function app.probe_b() returns int language sql as 'select 1'`);
await run(`alter default privileges revoke execute on functions from public`);
await run(`create function app.probe_c() returns int language sql as 'select 1'`);
const pv = await one(`select has_function_privilege('app_user','app.probe_a()','EXECUTE') a, has_function_privilege('app_user','app.probe_b()','EXECUTE') b, has_function_privilege('app_user','app.probe_c()','EXECUTE') c`);
say('SEC4b can app_user execute a NEW function in schema app?',
  `no fix: ${pv.a} | critique's fix (ALTER DEFAULT PRIVILEGES IN SCHEMA app …): ${pv.b} | global ALTER DEFAULT PRIVILEGES: ${pv.c}`);

// SEC4c ----------------------------------------------------------------------
const gTask = await idOf(`select id from tasks where project_id='${ops}' limit 1`);
say('SEC4c member inserts an Acme task reusing a Globex task id',
  await outcome(as(u.u3!, (trx) => sql`insert into tasks (id, organization_id, project_id, title, rank) values (${gTask}, ${acme}, ${web}, 'x', 'a0')`.execute(trx))));

await close();

