import { sql, type Kysely } from 'kysely';
import { openDatabase } from './src/db/database.js';
import { migrateToLatest } from './src/db/migrator.js';

const { db: typed, close } = await openDatabase();
await migrateToLatest(typed);
const db = typed.withoutPlugins() as unknown as Kysely<any>;
await sql.raw(`
  INSERT INTO users (email, display_name) VALUES ('m@x.test', 'M');
  INSERT INTO organizations (name, slug) VALUES ('Acme', 'acme');
  INSERT INTO organization_members SELECT o.id, u.id, 'member' FROM organizations o, users u;
  INSERT INTO projects (organization_id, key, name) SELECT id, 'WEB', 'Web' FROM organizations;
  INSERT INTO tasks (organization_id, project_id, title, status_id, rank)
    SELECT p.organization_id, p.id, 'T' || g, st.ids[1 + (g % 5)], 'a' || to_char(g, 'FM0000000')
      FROM projects p
      CROSS JOIN LATERAL (SELECT array_agg(id ORDER BY position) ids FROM task_statuses WHERE project_id = p.id) st
      CROSS JOIN generate_series(1, 20000) g;`).execute(db);
await sql`VACUUM ANALYZE tasks`.execute(db);
const me = (await sql<{ id: string }>`select id from users`.execute(db)).rows[0]!.id;
const s = (await sql<{ id: string; projectId: string }>`select id, project_id from task_statuses where name = 'Todo'`.execute(db)).rows[0] as any;
await db.transaction().execute(async (trx) => {
  await sql`SET LOCAL enable_seqscan = off`.execute(trx);
  await sql`SET LOCAL ROLE app_user`.execute(trx);
  await sql`SELECT set_config('app.user_id', ${me}, true)`.execute(trx);
  const plan = await sql.raw(`EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS) SELECT count(*) FROM tasks WHERE project_id='${s.project_id}' AND status_id='${s.id}' AND deleted_at IS NULL`).execute(trx);
  console.log(plan.rows.map((r: any) => String(Object.values(r)[0])).filter((l) => !l.trim().startsWith('Planning')).join('\n'));
});
await close();

