      const { first, after } = parseArgs(PageSchema, args);
      let query = ctx.db.selectFrom('projects').selectAll().where('organizationId', '=', organization.id);
      if (!args.includeArchived) query = query.where('archivedAt', 'is', null);
      if (after) {
        const cursor = decodeCursor(after);
        query = query.where(sql<boolean>`(key, id) > (${String(cursor.value)}, ${cursor.id}::uuid)`);
      }
      const rows = await query.orderBy('key').orderBy('id').limit(first + 1).execute();
