      const page = await ctx.loaders.columnTasks.load({ statusId: status.id, args: parsed });
      return toConnection(page, cursorFor(spec));
    },
  },

  Task: {
    project: async (task, _args, ctx) => must(await ctx.loaders.project.load(task.projectId), 'Project'),
    status: async (task, _args, ctx) => must(await ctx.loaders.status.load(task.statusId), 'Status'),
    assignee: (task, _args, ctx) => (task.assigneeId ? ctx.loaders.user.load(task.assigneeId) : null),
    labels: (task, _args, ctx) => ctx.loaders.labelsByTask.load(task.id),
    createdBy: (task, _args, ctx) => (task.createdBy ? ctx.loaders.user.load(task.createdBy) : null),
  },

  StatusCount: {
    status: async (entry, _args, ctx) => must(await ctx.loaders.status.load(entry.statusId), 'Status'),
  },

  AssigneeCount: {
    assignee: (entry, _args, ctx) => (entry.assigneeId ? ctx.loaders.user.load(entry.assigneeId) : null),
  },
};

