    const users: Record<string, string> = {};
    for (const [handle, displayName] of USERS) {
      const row = await trx
        .insertInto('users')
        .values({ email: `${handle}@example.test`, displayName })
        .returning('id')
        .executeTakeFirstOrThrow();
