        .insertInto('labels')
        .values(LABELS.map(([name, color]) => ({ organizationId: id, name, color })))
        .execute();
    }

    const projects: Record<string, string> = {};
    let taskCount = 0;
    for (const project of PROJECTS) {
      const organizationId = organizations[project.org]!; // eslint-disable-line @typescript-eslint/no-non-null-assertion -- seeded above
      const people = workers[project.org]!; // eslint-disable-line @typescript-eslint/no-non-null-assertion -- seeded above
      const { id: projectId } = await trx
        .insertInto('projects')
        .values({ organizationId, key: project.key, name: project.name, createdBy: people[0] ?? null })
        .returning('id')
        .executeTakeFirstOrThrow();
      projects[project.key] = projectId;

      // Default statuses come from the projects trigger, in position order.
      const statuses = await trx.selectFrom('taskStatuses').select(['id', 'position']).where('projectId', '=', projectId).orderBy('position').execute();
      const labels = await trx.selectFrom('labels').select('id').where('organizationId', '=', organizationId).execute();

