          .insertInto('tasks')
          .values(
            chunk.map((task) => ({
              organizationId,
              projectId,
              title: task.title,
              statusId: statuses[task.position]!.id, // eslint-disable-line @typescript-eslint/no-non-null-assertion -- 5 default statuses
              priority: task.priority,
              assigneeId: task.assigneeId,
              createdBy: task.createdBy,
              dueDate: task.dueDate,
              rank: rankQueues.get(task.position)!.shift()!, // eslint-disable-line @typescript-eslint/no-non-null-assertion -- one key per planned task
            })),
          )
          .returning('id') // Postgres returns rows in VALUES order
          .execute();
        const links = inserted.flatMap((row, index) =>
          chunk[index]!.labelIds.map((labelId) => ({ organizationId, taskId: row.id, labelId })), // eslint-disable-line @typescript-eslint/no-non-null-assertion -- same length as chunk
        );
        if (links.length > 0) await trx.insertInto('taskLabels').values(links).execute();
      }
      taskCount += planned.length;
    }

    return { users, organizations, projects, tasks: taskCount };
  });
}

