// Reads ESLint JSON output on stdin and prints "file:line  rule  message" per problem.
import { readFileSync } from 'node:fs';

const results = JSON.parse(readFileSync(0, 'utf8'));
for (const result of results) {
  const file = result.filePath.split('Compliance Foundry Assignment')[1].split('\\').join('/').slice(1);
  for (const message of result.messages) {
    console.log(`${file}:${message.line}  ${message.ruleId ?? ''}  ${message.message.slice(0, 120)}`);
  }
}

