import { readFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import {
  buildSchema,
  isEnumType,
  isInputObjectType,
  isInterfaceType,
  isObjectType,
  type GraphQLSchema,
} from 'graphql';
import { describe, expect, it } from 'vitest';
import { API_ROOT } from '../src/paths.js';

const load = async (path: string) => buildSchema(await readFile(path, 'utf8'));

function contractViolations(api: GraphQLSchema, design: GraphQLSchema): string[] {
  const problems: string[] = [];
  for (const type of Object.values(api.getTypeMap())) {
    if (type.name.startsWith('__')) continue;
    const designed = design.getType(type.name);
    if (!designed) {
      problems.push(`${type.name}: not in the design`);
      continue;
    }
    if (isEnumType(type) && isEnumType(designed)) {
      for (const value of type.getValues()) {
        if (!designed.getValue(value.name))
          problems.push(`${type.name}.${value.name}: not in the design`);
      }
    }
    if (
      (isObjectType(type) || isInterfaceType(type) || isInputObjectType(type)) &&
      (isObjectType(designed) || isInterfaceType(designed) || isInputObjectType(designed))
    ) {
      const designedFields = designed.getFields();
      for (const field of Object.values(type.getFields())) {
        const match = designedFields[field.name];
        if (!match) {
          problems.push(`${type.name}.${field.name}: not in the design`);
        } else if (String(match.type) !== String(field.type)) {
          problems.push(
            `${type.name}.${field.name}: ${String(field.type)} vs design ${String(match.type)}`,
          );
        } else if ('args' in field && 'args' in match) {
          for (const arg of field.args) {
            const designedArg = match.args.find((candidate) => candidate.name === arg.name);
            if (!designedArg || String(designedArg.type) !== String(arg.type)) {
              problems.push(`${type.name}.${field.name}(${arg.name}): differs from the design`);
            }
          }
        }
      }
    }
  }
  return problems;
}

