// Smoke test against the RUNNING dev server (http://localhost:4000): real HTTP, real tsx/Node module
// resolution (single graphql instance), real seeded 2,500-task project.
const API = 'http://localhost:4000';
const users = await (await fetch(`${API}/dev/users`)).json();
const as = (name) => users.find((user) => user.displayName.startsWith(name)).token;

async function gql(token, query, variables) {
  const started = performance.now();
  const response = await fetch(`${API}/graphql`, {
    method: 'POST',
    headers: { 'content-type': 'application/json', authorization: `Bearer ${token}` },
    body: JSON.stringify({ query, variables }),
  });
  const body = await response.json();
  return { status: response.status, ms: Math.round(performance.now() - started), ...body };
}

const carol = as('Carol');
const projects = await gql(carol, '{ organization(slug: "acme") { projects { edges { node { id key name } } } } }');
const web = projects.data.organization.projects.edges.find((edge) => edge.node.key === 'WEB').node;
console.log(`projects visible to Carol: ${projects.data.organization.projects.edges.map((e) => e.node.key).join(', ')}`);

const board = await gql(
  carol,
  `query ($p: ID!) { project(id: $p) { name statuses { name tasks(first: 25) { pageInfo { hasNextPage }
     edges { node { id identifier title priority dueDate isOverdue assignee { displayName } labels { name } } } } }
     taskSummary { total overdue byPriority { priority count } } } }`,
  { p: web.id },
);
const p = board.data.project;
console.log(`board "${p.name}" in ${board.ms} ms: ` + p.statuses.map((s) => `${s.name}=${s.tasks.edges.length}${s.tasks.pageInfo.hasNextPage ? '+' : ''}`).join(' | '));
console.log(`summary: total=${p.taskSummary.total} overdue=${p.taskSummary.overdue} priorities=${p.taskSummary.byPriority.map((b) => `${b.priority}:${b.count}`).join(',')}`);
const sample = p.statuses[1].tasks.edges[0].node;
console.log(`sample card: ${sample.identifier} "${sample.title}" ${sample.priority} due=${sample.dueDate} overdue=${sample.isOverdue} assignee=${sample.assignee?.displayName ?? '-'} labels=[${sample.labels.map((l) => l.name)}]`);

const tooBig = await gql(carol, `query ($p: ID!) { project(id: $p) { tasks(first: 500) { edges { cursor } } } }`, { p: web.id });
console.log(`first: 500 → ${tooBig.errors?.[0]?.extensions?.code}: ${tooBig.errors?.[0]?.message.split('\n')[0]}`);

const viewerMove = await gql(as('Erin'), `mutation ($i: MoveTaskInput!) { moveTask(input: $i) { task { id } } }`, {
  i: { id: sample.id, statusId: p.statuses[2].id ?? 'x' },
});
console.log(`viewer moveTask → ${viewerMove.errors?.[0]?.extensions?.code}: ${viewerMove.errors?.[0]?.message}`);

const statuses = await gql(carol, `query ($p: ID!) { project(id: $p) { statuses { id name } } }`, { p: web.id });
const inProgress = statuses.data.project.statuses.find((s) => s.name === 'In Progress');
const move = await gql(carol, `mutation ($i: MoveTaskInput!) { moveTask(input: $i) { task { identifier status { name } } } }`, {
  i: { id: sample.id, statusId: inProgress.id },
});
console.log(`carol moveTask ${move.data?.moveTask.task.identifier} → ${move.data?.moveTask.task.status.name} in ${move.ms} ms`);

const frank = await gql(as('Frank'), `query ($p: ID!) { project(id: $p) { id } }`, { p: web.id });
console.log(`Frank (Globex) sees Acme's project: ${JSON.stringify(frank.data)}`);

