      status: state.status,
      error: state.status === 'error' ? state.message : null,
      users,
      currentUser: users.find((user) => user.id === currentId) ?? null,
      switchUser,
      retry,
    };
  }, [state, currentId, switchUser, retry]);

  return <SessionContext value={value}>{children}</SessionContext>;
