  // column can also arrive in the next page.
  const tasks = useMemo(() => {
    const seen = new Set<string>();
    return status.tasks.edges
      .map((edge) => edge.node)
      .filter((task): task is TaskCardFieldsFragment => !seen.has(task.id) && Boolean(seen.add(task.id)));
  }, [status.tasks.edges]);
