    setLoadingMore(true);
    setLoadError(null);
    try {
      await client.query({
        query: ColumnMoreQuery,
        variables: { statusId: status.id, filter, pageSize: PAGE_SIZE, after: status.tasks.pageInfo.endCursor },
        fetchPolicy: 'network-only',
      });
    } catch (error) {
      setLoadError(describeError(error));
    } finally {
      setLoadingMore(false);
    }
  }

  const headingId = `column-${status.id}`;
  return (
