        ref={setNodeRef}
        className={cx(
          'min-h-24 flex-1 overflow-y-auto rounded-md px-2 pb-2 transition-colors',
          isOver && 'bg-accent/10 ring-2 ring-accent/40 ring-inset',
        )}
      >
        <SortableContext items={ids} strategy={verticalListSortingStrategy}>
