 * optimistic cache update lives in moveTask.ts. Viewers get a read-only board.
 */
import {
  closestCorners,
  DndContext,
  DragOverlay,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  type Announcements,
  type DragEndEvent,
  type DragStartEvent,
} from '@dnd-kit/core';
import { sortableKeyboardCoordinates } from '@dnd-kit/sortable';
import { useMemo, useState } from 'react';
import type { TaskCardFieldsFragment, TaskFilter } from '../../gql/graphql';
import { BoardColumn, type BoardStatus } from './BoardColumn';
import { neighboursAt, type MoveTarget } from './moveTask';
import { TaskCard } from './TaskCard';

/** What dnd-kit tells us about the element under the pointer (set in useSortable/useDroppable). */
interface DropData {
  type?: 'card' | 'column';
  statusId?: string;
}

export function Board({
  statuses,
  counts,
  filter,
  canEdit,
  onMove,
}: {
  statuses: BoardStatus[];
  counts: Map<string, number> | undefined;
  filter: TaskFilter | null;
  canEdit: boolean;
  onMove: (task: TaskCardFieldsFragment, target: MoveTarget) => void;
}) {
  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 6 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates }),
  );
  const [dragged, setDragged] = useState<TaskCardFieldsFragment | null>(null);

  const tasksById = useMemo(
    () => new Map(statuses.flatMap((status) => status.tasks.edges.map((edge) => [edge.node.id, edge.node] as const))),
    [statuses],
  );
  const columnTaskIds = useMemo(
    () => new Map(statuses.map((status) => [status.id, status.tasks.edges.map((edge) => edge.node.id)])),
    [statuses],
  );
  const statusNames = useMemo(() => new Map(statuses.map((status) => [status.id, status.name])), [statuses]);

  const identifierOf = (id: string | number) => tasksById.get(String(id))?.identifier ?? 'Task';
  const columnOf = (data: unknown) => statusNames.get((data as DropData | undefined)?.statusId ?? '') ?? 'a column';
  const announcements: Announcements = {
    onDragStart: ({ active }) => `Picked up ${identifierOf(active.id)}.`,
    onDragOver: ({ active, over }) =>
      over ? `${identifierOf(active.id)} moved over ${columnOf(over.data.current)}.` : undefined,
    onDragEnd: ({ active, over }) =>
      over
        ? `${identifierOf(active.id)} dropped in ${columnOf(over.data.current)}.`
        : `${identifierOf(active.id)} returned to its place.`,
    onDragCancel: ({ active }) => `Move cancelled. ${identifierOf(active.id)} returned to its place.`,
  };

  function handleDragStart({ active }: DragStartEvent) {
    setDragged(tasksById.get(String(active.id)) ?? null);
  }

  function handleDragEnd({ active, over }: DragEndEvent) {
    setDragged(null);
    const task = tasksById.get(String(active.id));
    const drop = over?.data.current as DropData | undefined;
    if (!task || !over || !drop?.statusId) return;

    const targetIds = columnTaskIds.get(drop.statusId) ?? [];
    // Dropped on a card: take that card's slot (same semantics as dnd-kit's arrayMove —
    // moving down lands after it, moving up lands before it; from another column,
    // before it). Dropped on a column's empty area: the end of that column.
    const overIndex = drop.type === 'card' ? targetIds.indexOf(String(over.id)) : -1;
    const index = overIndex >= 0 ? overIndex : targetIds.length;
    const target: MoveTarget = { toStatusId: drop.statusId, ...neighboursAt(targetIds, task.id, index) };

    // Nothing to do if the card would end up exactly where it already is.
    if (drop.statusId === task.status.id) {
      const current = neighboursAt(targetIds, task.id, targetIds.indexOf(task.id));
      if (current.afterTaskId === target.afterTaskId && current.beforeTaskId === target.beforeTaskId) return;
    }
    onMove(task, target);
  }

  return (
    <DndContext
      sensors={sensors}
      collisionDetection={closestCorners}
      onDragStart={handleDragStart}
      onDragEnd={handleDragEnd}
      onDragCancel={() => {
        setDragged(null);
      }}
      accessibility={{ announcements }}
    >
      <div className="flex h-[calc(100vh-19rem)] min-h-[28rem] gap-3 overflow-x-auto pb-2">
        {statuses.map((status) => (
          <BoardColumn
            key={status.id}
            status={status}
            total={counts?.get(status.id)}
            filter={filter}
            canEdit={canEdit}
          />
        ))}
      </div>
      <DragOverlay dropAnimation={null}>{dragged ? <TaskCard task={dragged} dragging /> : null}</DragOverlay>
    </DndContext>
  );
}

/**
 * PriorityChart.tsx — "Tasks by priority": the board's data visualization.
 *
 * Form (dataviz method): ONE series (task count) over five ordered categories →
 * horizontal bars, one hue, each row = name + bar + figure. No legend (the title
 * names the single series); value at each bar tip; no axis line or grid (every
 * value is labelled, so they'd be ink without information).
 * Marks: 16px bars (≤ 24px cap), 4px rounded data-end, square at the baseline.
 * Color: the validated series blue (`--series-1`, light and dark steps checked for
 * contrast/lightness on their surfaces). Text uses ink tokens, never the bar color.
 * Interaction: hovering a row shows count + share; screen readers get a table.
 */
import { Bar, BarChart, LabelList, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import type { TaskPriority } from '../../gql/graphql';
import { PRIORITIES } from './filters';

const LABELS: Record<TaskPriority, string> = {
  URGENT: 'Urgent',
  HIGH: 'High',
  MEDIUM: 'Medium',
  LOW: 'Low',
  NONE: 'No priority',
};

interface Row {
  label: string;
  count: number;
}

const percent = (part: number, whole: number) => (whole > 0 ? `${Math.round((part / whole) * 100)}%` : '0%');

function RowTooltip({ active, row, total }: { active: boolean; row: Row | undefined; total: number }) {
  if (!active || !row) return null;
  return (
    <div className="rounded-md border border-line bg-surface px-2.5 py-1.5 text-xs shadow-md">
      <div className="flex items-center gap-1.5">
        <span className="size-2 rounded-sm bg-series" aria-hidden />
        <span className="font-medium text-ink">{row.label}</span>
      </div>
      <div className="mt-0.5 text-ink-2">
        {row.count} tasks · {percent(row.count, total)}
      </div>
    </div>
  );
}

export function PriorityChart({ data }: { data: readonly { priority: TaskPriority; count: number }[] }) {
  const rows: Row[] = PRIORITIES.map((priority) => ({
    label: LABELS[priority],
    count: data.find((entry) => entry.priority === priority)?.count ?? 0,
  }));
  const total = rows.reduce((sum, row) => sum + row.count, 0);

  return (
    <figure className="rounded-lg border border-line bg-surface p-4">
      <figcaption>
        <span className="block text-sm font-medium">Tasks by priority</span>
        <span className="block text-xs text-ink-2">{total} tasks matching the current filters</span>
      </figcaption>

      {/* The chart is for sighted users; the table below carries the same numbers. */}
      <div className="mt-3 h-44" aria-hidden>
        <ResponsiveContainer width="100%" height="100%">
          <BarChart data={rows} layout="vertical" margin={{ top: 0, right: 44, bottom: 0, left: 0 }} barCategoryGap={6}>
            <XAxis type="number" hide domain={[0, 'dataMax']} />
            <YAxis
              type="category"
              dataKey="label"
              width={84}
              axisLine={false}
              tickLine={false}
              tick={{ fill: 'var(--ink-2)', fontSize: 12 }}
            />
            <Tooltip
              cursor={{ fill: 'var(--surface-2)' }}
              isAnimationActive={false}
              content={({ active, payload }) => (
                <RowTooltip active={active} row={payload[0]?.payload as Row | undefined} total={total} />
              )}
            />
            <Bar dataKey="count" fill="var(--series-1)" barSize={16} radius={[0, 4, 4, 0]} isAnimationActive={false}>
              <LabelList dataKey="count" position="right" fill="var(--ink-2)" fontSize={12} />
            </Bar>
          </BarChart>
        </ResponsiveContainer>
      </div>

      <table className="sr-only">
        <caption>Tasks by priority</caption>
        <thead>
          <tr>
            <th scope="col">Priority</th>
            <th scope="col">Tasks</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => (
            <tr key={row.label}>
              <th scope="row">{row.label}</th>
              <td>{row.count}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </figure>
  );
}

/**
 * SummaryPanel.tsx — headline numbers + the priority chart, for the filtered board.
 *
 * Data: the `BoardSummary` query (one GROUPING SETS pass on the server). It is a
 * separate query from the board on purpose: after a drag-and-drop move only this
 * small query is refetched, never the columns.
 * Tiles: label · value · one line of context. "Overdue" carries the reserved status
 * color as an icon next to its label — the number itself stays in ink.
 */
import { AlertIcon } from '../../components/icons';
import type { BoardSummaryQuery } from '../../gql/graphql';
import { cx } from '../../lib/cx';
import { PriorityChart } from './PriorityChart';

export type TaskSummary = NonNullable<BoardSummaryQuery['project']>['taskSummary'];

const compact = new Intl.NumberFormat(undefined, { notation: 'compact', maximumFractionDigits: 1 });
const format = (value: number) => (value >= 10_000 ? compact.format(value) : value.toLocaleString());
const percent = (part: number, whole: number) => (whole > 0 ? `${Math.round((part / whole) * 100)}%` : '0%');

function StatTile({
  label,
  value,
  detail,
  critical = false,
}: {
  label: string;
  value: number;
  detail: string;
  critical?: boolean;
}) {
  return (
    <div className="rounded-lg border border-line bg-surface p-4">
      <div className="flex items-center gap-1.5 text-sm text-ink-2">
        {critical && <AlertIcon className="size-4 text-critical" />}
        {label}
      </div>
      <div className={cx('mt-1 text-2xl font-semibold', critical && 'text-ink')}>{format(value)}</div>
      <div className="mt-0.5 text-xs text-ink-2">{detail}</div>
    </div>
  );
}

export function SummaryPanel({ summary }: { summary: TaskSummary | undefined }) {
  if (!summary) {
    return (
      <div role="status" aria-label="Loading summary" className="grid gap-3 lg:grid-cols-[minmax(0,1fr)_minmax(0,22rem)]">
        <div className="grid grid-cols-2 gap-3 xl:grid-cols-4">
          {[0, 1, 2, 3].map((tile) => (
            <div key={tile} className="h-[5.5rem] animate-pulse rounded-lg border border-line bg-surface" />
          ))}
        </div>
        <div className="h-[5.5rem] animate-pulse rounded-lg border border-line bg-surface" />
      </div>
    );
  }

  const countWhere = (categories: string[]) =>
    summary.byStatus
      .filter((entry) => categories.includes(entry.status.category))
      .reduce((sum, entry) => sum + entry.count, 0);
  const open = countWhere(['BACKLOG', 'UNSTARTED', 'STARTED']);
  const completed = countWhere(['COMPLETED']);
  const unassigned = summary.byAssignee.find((entry) => entry.assignee === null)?.count ?? 0;

  return (
    <section aria-label="Board summary" className="grid gap-3 lg:grid-cols-[minmax(0,1fr)_minmax(0,22rem)]">
      <div className="grid grid-cols-2 content-start gap-3 xl:grid-cols-4">
        <StatTile label="Total tasks" value={summary.total} detail={`${format(open)} open`} />
        <StatTile
          label="Overdue"
          value={summary.overdue}
          critical={summary.overdue > 0}
          detail={open > 0 ? `${percent(summary.overdue, open)} of open tasks` : 'No open tasks'}
        />
        <StatTile label="Completed" value={completed} detail={`${percent(completed, summary.total)} of all tasks`} />
        <StatTile label="Unassigned" value={unassigned} detail={`${percent(unassigned, summary.total)} of all tasks`} />
      </div>
      <PriorityChart data={summary.byPriority} />
    </section>
  );
}

